head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > P > sortType]<br/>DataList 모듈을 정렬할때 적용될 Column 의 데이터형을 설정합니다.",
    "validation" : [
        "미설정 또는 numberFirst 설정 시 Column 의 dataType 속성값이 'number' 또는 'bigDecimal' 이면 Column 값을 숫자로 처리하여 정렬합니다.",
        "dataType 설정 시 Column 의 dataType 속성값을 기준으로 Column 값을 숫자 또는 문자로 처리하여 정렬합니다.",
        "dataType 설정 시 dataType='number','bigDecimal' 이면 Column 값을 숫자로 처리하여 정렬합니다.",
        "dataType 설정 시 dataType='text','date','time','json' 이면 Column 값을 문자로 처리하여 정렬합니다.",
        "number 설정 시 Column 의 dataType 속성값에 관계없이 Column 값을 숫자로 처리하여 정렬합니다.",
        "text 설정 시 Column 의 dataType 속성값에 관계없이 Column 값을 문자로 처리하여 정렬합니다.",
        "bigDecimal 설정 시 Column 의 dataType 속성값에 관계없이 Column 값을 숫자로 처리하여 정렬합니다.",
        "sortType 속성값이 'numberFirst' 이 아니면 sortType 속성값에 맞게 Column 값을 숫자 또는 문자로 처리하여 정렬합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // 조건 설정       
    let properties = {
        sortType: con_sortType.getText(),        
    };

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strGridView = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataList ' + strNameSpace + ' ' + cList + ' id="target1" baseNode="list" repeatNode="map">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="label" name="name1" dataType="'+con_dataType.getText()+'"></w2:column>';    
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[10]]></label>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[1]]></label>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[2]]></label>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[A1]]></label>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[A10]]></label>';
    strTarget += '</w2:row>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';    


    $p.data.create(strTarget);

    // gridView 생성
    strGridView += '<w2:gridView ' + strNameSpace + ' sortable="true" rowStatusVisible="true" checkAllType="false" id="gridView1" dataList="target1" style="width:500px;height:300px;" ev:onsort="scwin.gridView1_onsort">';
    strGridView += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strGridView += '<w2:header style="" id="header1">';
    strGridView += '<w2:row style="" id="row1">';
    strGridView += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';    
    strGridView += '</w2:row>';
    strGridView += '</w2:header>';
    strGridView += '<w2:gBody style="" id="gBody1">';
    strGridView += '<w2:row style="" id="row2">';
    strGridView += '<w2:column width="120" style="" id="label" value=""></w2:column>';    
    strGridView += '</w2:row>';
    strGridView += '</w2:gBody>';
    strGridView += '</w2:gridView>';    

    // gridView 생성
    scwin["gridView1"] = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView,
        grp_comp
    );    

    target1.clearSort();
}   



scwin.btn_getAllJSON_onclick = function (e) {
    let rtn = target1.getAllJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_sortDescending_onclick = function (e) {
	target1.sort("label", 1);

    scwin.btn_getAllJSON_onclick();	
};



scwin.btn_Ascending_onclick = function (e) {
	target1.sort("label", 0);

    scwin.btn_getAllJSON_onclick();		
};
